&= \cos \theta - \frac{1}{2} \cos \theta - \frac{\sqrt{3}}{2} \sin \theta - \frac{1}{2} \cos \theta + \frac{\sqrt{3}}{2} \sin \theta \\
&= 0,
\end{align*}so
\begin{align*}
CE_1^2 + CE_2^2 + CE_3^2 + CE_4^2 &= 2s^2 - 2s^2 \cos \theta + 2s^2 - 2s^2 \cos (240^\circ + \theta) \\
